C={}
def ch(i,text,reason,cross): C[str(i)]={'text':text,'reason':reason,'cross':cross}
def style(i,text,reason='Mevcut Türkçe temel anlamı taşıyordu ancak sözdizimi, hitap düzeyi veya konuşma doğallığı zayıftı; satır tüm diller okunarak doğal Türkçeyle yeniden kuruldu.',cross='JP özgün metin ile FR/DE/IT/ES aynı temel anlamı doğruluyor; değişiklik bilgi eklemeden Türkçe akış, ton ve karakter sesi için yapıldı.'):
    ch(i,text,reason,cross)
def critical(i,text,reason='Mevcut Türkçede anlam, özne/nesne ilişkisi veya sahne mantığını etkileyen bir hata vardı; satır tüm dillerle karşılaştırılarak düzeltildi.',cross='JP özgün metin ve diğer resmî yerelleştirmelerin ortak anlamı yeni Türkçeyi destekliyor.'):
    ch(i,text,reason,cross)
def sound(i,text):
    ch(i,text,'Pokémon vokalizasyonu “çığlık” olarak genellenmişti; sahne etiketi bağlamı bozmadan nötr “Pokémon sesi” biçiminde standardize edildi.','JP 鳴き声 nötr bir Pokémon sesi/vokalizasyonu belirtir; EN de “Pokémon cry” teknik etikettir. Bu satırda gerçek bir çığlık anlamı zorunlu değil.')
def term(i,text,reason='Mevcut Türkçedeki terim bağlama veya önceki manuel terminolojiye uymuyordu; çok-dilli karşılaştırmayla tutarlılaştırıldı.',cross='JP ve FR/DE/IT/ES karşılıkları aynı kavramı doğruluyor; önceki manuel turlarda kullanılan Türkçe terminolojiyle tutarlılık sağlandı.'):
    ch(i,text,reason,cross)

